CREATE OR REPLACE FUNCTION public.award_social_points() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='friendships' THEN IF NEW.status='accepted' AND OLD.status='pending' THEN INSERT INTO public.point_events(user_id,reason,points,source_key) VALUES(NEW.requester_id,'New friend',10,'friend:'||NEW.recipient_id),(NEW.recipient_id,'New friend',10,'friend:'||NEW.requester_id) ON CONFLICT DO NOTHING; END IF; ELSIF TG_TABLE_NAME='stories' THEN INSERT INTO public.point_events(user_id,reason,points,source_key) VALUES(NEW.owner_id,'Daily story',5,'story:'||to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD')) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;